  6	stan_code <- "
  7	functions {
  8	  matrix cov_ard_sqexp(matrix X, vector rho, real alpha, real jitter) {
  9	    int N = rows(X);
 10	    int D = cols(X);
 11	    matrix[N, N] K;
 12	
 13	    for (i in 1:N) {
 14	      K[i, i] = square(alpha) + jitter;
 15	      for (j in (i + 1):N) {
 16	        real s = 0;
 17	        for (d in 1:D) {
 18	          real t = (X[i, d] - X[j, d]) / rho[d];
 19	          s += t * t;
 20	        }
 21	        K[i, j] = square(alpha) * exp(-0.5 * s);
 22	        K[j, i] = K[i, j];
 23	      }
 24	    }
 25	    return K;
 26	  }
 27	
 28	  matrix cross_cov_ard(matrix X, matrix X_new, vector rho, real alpha) {
 29	    int N = rows(X);
 30	    int M = rows(X_new);
 31	    int D = cols(X); // == cols(X_new)
 32	    matrix[N, M] Kx;
 33	    for (i in 1:N) {
 34	      for (j in 1:M) {
 35	        real s = 0;
 36	        for (d in 1:D) {
 37	          real t = (X[i, d] - X_new[j, d]) / rho[d];
 38	          s += t * t;
 39	        }
 40	        Kx[i, j] = square(alpha) * exp(-0.5 * s);
 41	      }
 42	    }
 43	    return Kx;
 44	  }
 45	}
 46	
 47	data {
 48	  int<lower=1> N;
 49	  int<lower=1> D;
 50	  matrix[N, D] X;
 51	  int<lower=1> P;
 52	  matrix[N, P] H;
 53	  vector[N] y;
 54	  real<lower=0> jitter;
 55	
 56	  int<lower=0> N_new;
 57	  matrix[N_new, D] X_new;
 58	  matrix[N_new, P] H_new;
 59	}
 60	
 61	parameters {
 62	  vector[P] beta;
 63	  real<lower=0> alpha;
 64	  vector<lower=0>[D] rho;
 65	  real<lower=0> sigma;
 66	}
 67	
 68	transformed parameters {
 69	  vector[N] mu = H * beta;
 70	  matrix[N, N] K = cov_ard_sqexp(X, rho, alpha, jitter)
 71	                   + diag_matrix(rep_vector(square(sigma), N));
 72	  matrix[N, N] L_K = cholesky_decompose(K);
 73	}
 74	
 75	model {
 76	  beta  ~ normal(0, 1);
 77	  alpha ~ normal(0, 1.5);
 78	  rho   ~ lognormal(0, 1);
 79	  sigma ~ normal(0, 0.5);
 80	  y ~ multi_normal_cholesky(mu, L_K);
 81	}
 82	
 83	generated quantities {
 84	  vector[N_new] y_new;
 85	  if (N_new > 0) {
 86	    matrix[N, N_new] K_x_xnew = cross_cov_ard(X, X_new, rho, alpha);
 87	    matrix[N_new, N_new] K_new = cov_ard_sqexp(X_new, rho, alpha, jitter);
 88	    vector[N] resid = y - (H * beta);
 89	
 90	    vector[N] alpha_vec = mdivide_left_tri_low(L_K, resid);
 91	    alpha_vec = mdivide_left_tri_low(L_K', alpha_vec);
 92	
 93	    vector[N_new] f_mean = (K_x_xnew' * alpha_vec);
 94	    matrix[N, N_new] v = mdivide_left_tri_low(L_K, K_x_xnew);
 95	    vector[N_new] f_var = to_vector(diagonal(K_new)) - to_vector(columns_dot_self(v));
 96	    for (m in 1:N_new) {
 97	      real m_mean = (H_new[m] * beta) + f_mean[m];
 98	      real m_sd   = sqrt(f_var[m] + square(sigma));
 99	      y_new[m] = normal_rng(m_mean, m_sd);
100	    }
101	  }
102	}
